import{_ as l,a0 as i,w as n,s as p,ao as d,I as o,x as e,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"企業應該選擇無服務器計算嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"企業應該選擇無服務器計算嗎？ | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"企業應該選擇無服務器計算嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"企業應該選擇無服務器計算嗎？ | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20211203 Should Businesses Opt for Serverless Computing-","title":"企業應該選擇無服務器計算嗎？","tag":"202207","desc":""},"relativePath":"202207/20211203 Should Businesses Opt for Serverless Computing-.md","filePath":"[post].md"}'),u={name:"202207/20211203 Should Businesses Opt for Serverless Computing-.md"};function h(m,a,b,f,S,x){const t=i("Link");return n(),p("div",null,[a[15]||(a[15]=d('<h1 id="企業應該選擇無服務器計算嗎" tabindex="-1">企業應該選擇無服務器計算嗎？ <a class="header-anchor" href="#企業應該選擇無服務器計算嗎" aria-label="Permalink to “企業應該選擇無服務器計算嗎？”">​</a></h1><blockquote><p>無服務器計算將服務器從規劃中移除，使企業能夠專注於應用功能。那麼，企業是不是都應該選擇無服務器計算呢？讓我們來探究一下吧！</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202207/01/113921u4sjl5cczwj3tjbu.jpg" alt=""></p><p>直至不久之前，幾乎每個產品經理都會將他/她的工程資源，分成兩個獨立的團隊 —— 開發團隊和運維團隊。開發團隊通常參與編碼、測試和構建應用功能，而運維團隊負責應用程序的交付、部署和運行維護。</p><p>當開發團隊構建電商應用時，運維團隊會搭建好服務器來託管該應用。搭建服務器涉及到許多方面，其中包括：</p><ul><li>選擇合適的硬件和操作系統</li><li>應用所需的補丁集</li><li>搭建所需服務器環境，如 JDK、Python、Tomcat、NodeJS 等</li><li>部署、配置和提供實際的應用</li><li>打開並固定合適的端口</li><li>搭建所需的資料庫引擎</li></ul><p>……這個名單還在繼續。</p><p>除此之外，管理人員還對容量規劃感到頭疼。畢竟，任何重要應用都應始終保持 100% 可用、可靠且可擴展。這需要對硬件進行最佳投資。眾所周知，在一些關鍵時期，硬件短缺會導致業務損失，而硬件冗餘又會損害利潤。因此，無論應用是針對本地數據中心，還是針對雲基礎架構，容量規劃都是至關重要的。到目前為止，很明顯，企業不僅在功能構建上投入了大量的精力，還在功能交付上也花費了大量的時間。</p><p><ruby>無服務器計算<rt>Serverless computing</rt></ruby>旨在提供一種無縫的方式來交付功能，而無需擔心服務器的設置和維護。換句話説，無服務器計算平台提供了一個“<ruby>即用型<rt>ready-to-use</rt></ruby>”環境，企業可以儘快將應用程序構建和部署為一些較小的功能。這就是為什麼這種方法被稱為“<ruby>功能即服務<rt>Function as a Service</rt></ruby>”（FaaS）。</p><p>請記住，無服務器計算中仍然存在服務器，但它由 AWS、微軟和谷歌等 FaaS 供應商負責。</p><p>例如，AWS 以 “Lambda 函數”的形式提供了一個無服務器計算環境。開發人員可以選擇將應用程序構建為一組 Lambda 函數，這些函數可以用 NodeJS、Java、Python 和其他一些語言編寫。AWS 提供了一個現成的環境來部署這些函數。它還提供了即用​​型資料庫服務器、文件服務器、應用程序網關和身份驗證服務器等。</p><p>同樣，微軟 Azure 也提供了一個環境，它可以用 C# 等語言構建和部署 Azure 函數。</p><h3 id="為什麼選擇無服務器" tabindex="-1">為什麼選擇無服務器？ <a class="header-anchor" href="#為什麼選擇無服務器" aria-label="Permalink to “為什麼選擇無服務器？”">​</a></h3><p>有兩個主要因素推動了無服務器計算的普及。</p><h4 id="_1、即用型環境" tabindex="-1">1、即用型環境 <a class="header-anchor" href="#_1、即用型環境" aria-label="Permalink to “1、即用型環境”">​</a></h4><p>顯然，這是無服務器計算的最大賣點。企業無需提前採購/預訂硬件或實例，也無需操心許可證，以及設置和配置服務器。他們不需要為擴大和縮小規模而煩惱。所有這些都由 FaaS 供應商負責。</p><h4 id="_2、最優成本" tabindex="-1">2、最優成本 <a class="header-anchor" href="#_2、最優成本" aria-label="Permalink to “2、最優成本”">​</a></h4><p>由於 FaaS 供應商總是根據環境的利用率向客户收費（按使用付費模式），因此企業無需擔心前期成本和資源浪費。例如，AWS 根據 Lambda 函數接收的請求數量、在數據表上運行的查詢數量等指標來向客户端收費。</p><h3 id="無服務器計算的挑戰" tabindex="-1">無服務器計算的挑戰 <a class="header-anchor" href="#無服務器計算的挑戰" aria-label="Permalink to “無服務器計算的挑戰”">​</a></h3><p>與任何其他方法一樣，無服務器計算也不是每個人都可以盲目遵循的完美方法。它本身也有一系列限制。以下是其中的幾個。</p><h4 id="_1、供應商鎖定" tabindex="-1">1、供應商鎖定 <a class="header-anchor" href="#_1、供應商鎖定" aria-label="Permalink to “1、供應商鎖定”">​</a></h4><p>當使用無服務器計算時，第一個也是最重要的問題就是，Lambda 或 Azure 等函數將使用供應商提供的 API 來編寫。例如，使用 AWS Lambda API 編寫的函數無法部署到 Google Cloud 中，反之亦然。因此，無服務器計算迫使企業在許多年內，只能使用同一家供應商。並且，應用的成功或失敗不僅取決於它的功能，還取決於供應商在性能等方面的能力。</p><h4 id="_2、編程語言" tabindex="-1">2、編程語言 <a class="header-anchor" href="#_2、編程語言" aria-label="Permalink to “2、編程語言”">​</a></h4><p>沒有哪家無服務器計算平台支持所有的編程語言。此外，對於它支持的編程語言，它也可能不支持其所有版本。這樣一來，應用開發團隊只能選擇供應商提供的語言。就團隊的能力而言，這可能是非常關鍵的。</p><h4 id="_3、最優成本-真的嗎" tabindex="-1">3、最優成本，真的嗎？ <a class="header-anchor" href="#_3、最優成本-真的嗎" aria-label="Permalink to “3、最優成本，真的嗎？”">​</a></h4><p>其實也不一定，這一切都取決於資源的使用情況。如果你的應用正在承受巨大的負載，例如每秒數百萬個請求，那麼你所支付的費用可能會過高。在這樣的規模下，在本地或雲端擁有自己的服務器可能會更便宜。這並不意味着具有 Web 規模的應用不適合用無服務器計算。歸根結底，它還是取決於你的平台的構建方式，以及你與供應商簽署的協議。</p><h4 id="_4、生態系統" tabindex="-1">4、生態系統 <a class="header-anchor" href="#_4、生態系統" aria-label="Permalink to “4、生態系統”">​</a></h4><p>沒有哪個應用是為了一個孤立的環境而編寫的。它總是需要其他組件，如數據存儲、資料庫、安全引擎、網關、消息服務器、隊列、緩存等。每個平台都提供自己的一組此類工具。例如，AWS 提供了 Dynamo DB 作為其 NoSQL 解決方案之一。顯然，其他供應商也提供了自己的 NoSQL 解決方案。因此，團隊又會被迫地基於所選平台來構建應用程序。儘管大多數商業 FaaS 供應商都為特定需求提供了多個組件，但並非每個組件都可能是同類型中最佳的。</p><h3 id="為什麼不考慮容器呢" tabindex="-1">為什麼不考慮容器呢？ <a class="header-anchor" href="#為什麼不考慮容器呢" aria-label="Permalink to “為什麼不考慮容器呢？”">​</a></h3><p>在過去十年中，我們中的許多人都遷移到了容器化部署模型，因為它們為昂貴的物理機或虛擬機提供了一種輕量級的替代方案。有了 Kubernetes 等編排工具後，我們樂於部署容器化應用，同時也滿足了 Web 規模的要求。容器提供了與底層環境一定程度的隔離，這使得部署相對容易。但是，我們仍然需要在硬件（本地或雲）、許可證、網絡、配置等方面進行投資，這需要具有前瞻性的規劃、合適的技術能力和仔細的監控。無服務器計算，儘管它也有自己的優點和缺點，但它讓我們把這些責任也擺脱了。</p><h3 id="展望未來" tabindex="-1">展望未來 <a class="header-anchor" href="#展望未來" aria-label="Permalink to “展望未來”">​</a></h3><p>我們正處於持續開發、持續集成和持續部署的時代。每個企業都面臨着競爭。產品<ruby>上市時間<rt>Time to market</rt></ruby>（TTM）在吸引客户、留住客户這兩個方面，發揮着重要作用。在這種背景下，企業喜歡花更多時間來儘可能快地推出功能，而不是在部署和維護的細節上苦苦掙扎。無服務器計算有可能滿足這些需求。大玩家們正在投入鉅額資金，以使 FaaS 儘可能地無縫且經濟。無服務器計算的未來看起來是一片光明。</p><hr>',33)),o("p",null,[a[1]||(a[1]=e("via: ",-1)),r(t,{href:"https://www.opensourceforu.com/2021/12/should-businesses-opt-for-serverless-computing/"},{default:s(()=>[...a[0]||(a[0]=[e("https://www.opensourceforu.com/2021/12/should-businesses-opt-for-serverless-computing/",-1)])]),_:1})]),o("p",null,[a[6]||(a[6]=e("作者：",-1)),r(t,{href:"https://www.opensourceforu.com/author/krishna-mohan-koyya/"},{default:s(()=>[...a[2]||(a[2]=[e("Krishna Mohan Koyya",-1)])]),_:1}),a[7]||(a[7]=e(" 選題：",-1)),r(t,{href:"https://github.com/lkxed"},{default:s(()=>[...a[3]||(a[3]=[e("lkxed",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),r(t,{href:"https://github.com/lkxed"},{default:s(()=>[...a[4]||(a[4]=[e("lkxed",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:s(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),o("p",null,[a[12]||(a[12]=e("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:s(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const g=l(u,[["render",h]]);export{C as __pageData,g as default};
